"""Check files generated by tests/document-groups.cjs; no API calls or dependencies."""
from pathlib import Path
import shutil
import subprocess
import xml.etree.ElementTree as ET
import zipfile

out = Path('.test-output')
ns = {'p': 'http://www.hancom.co.kr/hwpml/2011/paragraph', 'h': 'http://www.hancom.co.kr/hwpml/2011/head'}
with zipfile.ZipFile(out / 'grouped-output.hwpx') as archive:
    raw = archive.read('Contents/section0.xml').decode()
    body = ET.fromstring(raw)
    header = ET.fromstring(archive.read('Contents/header.xml'))
assert raw.count('수정한 공통 처리 목적') == 1
assert raw.count('rowSpan="2"') >= 2
choices = [table for table in body.findall('.//p:tbl', ns) if table.get('rowCnt') == '1' and table.get('colCnt') == '2']
assert len(choices) == 3
for table in choices:
    assert table.get('borderFillIDRef') == '1'
    cells = table.findall('.//p:tc', ns)
    assert all(cell.get('borderFillIDRef') == '1' for cell in cells)
    for cell, align in zip(cells, ['LEFT', 'RIGHT']):
        paragraph_id=cell.find('.//p:p', ns).get('paraPrIDRef')
        prop=header.find(f'.//h:paraPr[@id="{paragraph_id}"]', ns)
        assert prop.find('h:align',ns).get('horizontal')==align
        assert all(spacing.get('value')=='130' for spacing in prop.findall('.//h:lineSpacing',ns))
for paragraph_id, expected in [('21', 'LEFT'), ('23', 'RIGHT')]:
    assert header.find(f'.//h:paraPr[@id="{paragraph_id}"]/h:align', ns).get('horizontal') == expected
border = header.find('.//h:borderFill[@id="1"]', ns)
assert all(border.find('h:' + side + 'Border', ns).get('type') == 'NONE' for side in ['left', 'right', 'top', 'bottom'])
agency = next(p for p in body.findall('.//p:p', ns) if ''.join(''.join(p.itertext()).split()) == '시험기관귀중')
agency_style = agency.find('p:run', ns).get('charPrIDRef')
style = header.find(f'.//h:charPr[@id="{agency_style}"]', ns)
assert style.get('height') == '1500' and style.get('textColor') == '#000000'
properties = header.find('.//h:charProperties', ns)
assert int(properties.get('itemCnt')) == len(properties)
print('PASS HWPX merged cells, borderless choice tables, alignment and larger agency font')
if shutil.which('pdftotext'):
    def pdf_text(path):
        text = subprocess.check_output(['pdftotext', '-raw', str(path), '-'], text=True)
        return ''.join(text.split())
    assert pdf_text(out / 'grouped-output.pdf').count('수정한공통처리목적') == 1
    text = pdf_text(out / 'grouped-long.pdf')
    assert all(text.count('연속검증' + str(i).zfill(3)) == 1 for i in range(100))
    print('PASS merged PDF text and all 100 long-cell tokens appear exactly once across pages')
else:
    print('SKIP PDF text extraction: install pdftotext to run this check')
